def simulate_device(N, Q, queries):
    boxes = [0] * (N + 1)

    def update(L, R, A, B):
        for X in range(L, R + 1):
            boxes[X] = ((X - L + 1) * A) % B

    def query(L, R):
        return sum(boxes[L:R + 1])

    results = []
    for query_type, L, R, *args in queries:
        if query_type == 1:
            A, B = args
            update(L, R, A, B)
        elif query_type == 2:
            results.append(query(L, R))

    return results

