def simulate_device(N, Q, queries):
    def process_command(boxes, command):
        if command[0] == 1:
            L, R, A, B = map(int, command[1:])
            for i in range(L-1, R):
                boxes[i] = ((i-L+1) * A) % B
        elif command[0] == 2:
            L, R = map(int, command[1:])
            return sum(boxes[L-1:R])

    boxes = [0] * N
    results = []
    for query in queries:
        result = process_command(boxes, query)
        if isinstance(result, int):
            results.append(result)
    return results

